shellCommands.command:
sed -i 's|  const open = i + run - 3;\n||' src/markdown/parse.ts && node -e "
const fs=require('fs');let s=fs.readFileSync('src/markdown/parse.ts','utf8');
s=s.replace(\`  const open = i + run - 3;
  if (open > i) return null; // лишние символы уйдут в текст по одному\`, \`  if (run > 3) return null; // лишние символы уйдут в текст по одному\`);
fs.writeFileSync('src/markdown/parse.ts',s);" && grep -n "run > 3" src/markdown/parse.ts

cat > vite.config.ts <<'EOF'
/// <reference types="vitest/config" />
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    environment: 'node',
    css: false,
    server: {
      deps: {
        // стили uikit импортируются из ESM-сборки; vitest должен обработать их сам
        inline: [/@gravity-ui\/uikit/],
      },
    },
  },
});
EOF
npx tsc --noEmit && npx vitest run 2>&1 | tail -25
